import { MARINE_CREATURES } from './marine-creatures'

// Bound generated leaves after generation; leave prompts general so user naming instructions own style.
export const MAX_BRANCH_NAME_WORDS = 4

const CREATURE_NAMES_LOWER = new Set(MARINE_CREATURES.map((name) => name.toLowerCase()))

function normalizeName(name: string): string {
  return name.trim().toLowerCase()
}

/** Auto-rename only Orca-picked creature leaves, including numbered collision variants; never overwrite a deliberately user-named branch. */
export function isAutoGeneratedCreatureBranchName(branchLeaf: string): boolean {
  const normalized = normalizeName(branchLeaf)
  if (!normalized) {
    return false
  }
  // Strip one creation collision suffix before testing creature membership.
  const base = normalized.replace(/-\d+$/, '')
  return CREATURE_NAMES_LOWER.has(base)
}

/**
 * Turn raw model output into a safe, short kebab-case branch leaf. Returns ''
 * when nothing usable remains, which callers treat as "skip the rename".
 */
export function sanitizeBranchSlug(raw: string, maxWords = MAX_BRANCH_NAME_WORDS): string {
  const words = raw
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .split('-')
    .filter(Boolean)
  if (words.length === 0) {
    return ''
  }
  return words.slice(0, maxWords).join('-')
}

/** Strip only a matching configured prefix from generated slugs to avoid doubled prefixes/display names. Prefix-only output becomes empty so callers skip rename; genuine leading content survives. */
export function stripConfiguredBranchPrefix(
  slug: string,
  prefix: string | null | undefined
): string {
  if (!prefix) {
    return slug
  }
  const prefixSlug = prefix
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
  if (!prefixSlug) {
    return slug
  }
  if (slug === prefixSlug) {
    return ''
  }
  return slug.startsWith(`${prefixSlug}-`) ? slug.slice(prefixSlug.length + 1) : slug
}

/** Humanize the branch slug for sidebar naming so workspace labels stay aligned with renamed branches. */
export function humanizeBranchSlug(slug: string): string {
  const joined = slug.split('-').filter(Boolean).join(' ')
  if (!joined) {
    return ''
  }
  return joined.charAt(0).toUpperCase() + joined.slice(1)
}

export type BranchNameWorkContext = {
  /** The user's first prompt to the agent in this workspace. */
  firstPrompt: string
  /** The agent's first response, when it has already arrived. Optional because
   *  the rename fires as soon as work begins, before a reply may exist. */
  assistantMessage?: string
}

/** Share naming prompts across local/SSH. Keep defaults general for user Source Control AI/template guidance; enforce Git safety/length after generation via sanitizeBranchSlug. */
export function buildBranchNamePrompt(context: BranchNameWorkContext, customPrompt = ''): string {
  const sections: string[] = []
  const prompt = customPrompt.trim()
  // Lead with user guidance so it owns naming style over the default.
  if (prompt) {
    sections.push(prompt, '')
  }
  sections.push(
    prompt
      ? 'Generate a git branch name that summarizes the coding task described below.'
      : 'Generate a short git branch name that summarizes the coding task described below.',
    'Output ONLY the branch name on a single line, nothing else.',
    ''
  )
  sections.push('User request:', context.firstPrompt.trim())
  const assistant = context.assistantMessage?.trim()
  if (assistant) {
    sections.push('', "Agent's initial response:", assistant)
  }
  return sections.join('\n')
}

  writeSourceControlAiSettings,
  displayedGitUsername,
  hasUnsavedBranchPromptChanges = false,
  onBranchPromptDirtyChange,
  branchPromptDiscardSignal,
  settingsSearchQuery
}: GitPaneProps): React.JSX.Element {
  const storeSearchQuery = useAppStore((s) => s.settingsSearchQuery)
  const searchQuery = settingsSearchQuery ?? storeSearchQuery
  const keepLocalMainUpToDateTitle = getKeepLocalMainUpToDateTitle()

  const isBranchPrefixInputMode = settings.branchPrefix !== 'none'
  // Local drafts preserve caret/fast typing through async IPC; adopt external reloads but ignore delayed echoes of our own edits.
  const [customPrefixDraft, setCustomPrefixDraft] = useState(settings.branchPrefixCustom)
  const lastCommittedPrefixRef = useRef(settings.branchPrefixCustom)
  useEffect(() => {
    if (settings.branchPrefixCustom !== lastCommittedPrefixRef.current) {
      lastCommittedPrefixRef.current = settings.branchPrefixCustom
      setCustomPrefixDraft(settings.branchPrefixCustom)
    }
  }, [settings.branchPrefixCustom])
  const branchPrefixInputValue =
    settings.branchPrefix === 'git-username' ? displayedGitUsername : customPrefixDraft

  const visibleSections = [
    matchesSettingsSearch(searchQuery, {
      title: translate('auto.components.settings.GitPane.330f584b50', 'Branch Prefix'),
      description: translate(
        'auto.components.settings.GitPane.1ffaadf0a0',
        'Prefix added to branch names when creating worktrees.'
      ),
      keywords: [
        translate('auto.components.settings.GitPane.cc63fce906', 'branch naming'),
        translate('auto.components.settings.GitPane.2351aa5a31', 'git username'),
        translate('auto.components.settings.GitPane.813e15b346', 'custom')
      ]
    }) ? (
      <SearchableSetting
        key="branch-prefix"
        title={translate('auto.components.settings.GitPane.330f584b50', 'Branch Prefix')}
        description={translate(
          'auto.components.settings.GitPane.1ffaadf0a0',
          'Prefix added to branch names when creating worktrees.'
        )}
        keywords={['branch naming', 'git username', 'custom']}
        className="space-y-3"
      >
        <div className="space-y-0.5">
          <Label>{translate('auto.components.settings.GitPane.330f584b50', 'Branch Prefix')}</Label>
          <p className="text-xs text-muted-foreground">
            {translate(
              'auto.components.settings.GitPane.1ec5c91e1d',
              'Choose whether branch names use your Git username, a custom prefix, or no prefix.'
            )}
          </p>
        </div>
        <div className="flex w-fit gap-1 rounded-md border border-border/50 p-1">
          {(['git-username', 'custom', 'none'] as const).map((option) => (
            <button
              key={option}
              onClick={() => updateSettings({ branchPrefix: option })}
              className={`rounded-sm px-3 py-1 text-sm transition-colors ${
                settings.branchPrefix === option
                  ? 'bg-accent font-medium text-accent-foreground'
                  : 'text-muted-foreground hover:text-foreground'
              }`}
            >
              {option === 'git-username'
                ? translate('auto.components.settings.GitPane.a182c5125e', 'Git Username')
                : option === 'custom'
                  ? translate('auto.components.settings.GitPane.1f32ba27a6', 'Custom')
                  : translate('auto.components.settings.GitPane.3d172725cc', 'None')}
            </button>
          ))}
        </div>
        {isBranchPrefixInputMode && (
          <Input
            value={branchPrefixInputValue}
            onChange={(e) => {
              const next = e.target.value
              lastCommittedPrefixRef.current = next
              setCustomPrefixDraft(next)
              updateSettings({ branchPrefixCustom: next })
            }}
            placeholder={
              settings.branchPrefix === 'git-username'
                ? translate(
                    'auto.components.settings.GitPane.aefa1ecb59',
                    'No git username configured'
                  )
                : translate('auto.components.settings.GitPane.b559bf9899', 'e.g. feature')
            }
            className="max-w-xs"
            readOnly={settings.branchPrefix === 'git-username'}
          />
        )}
        {isBranchPrefixInputMode && <BranchPrefixFeedback rawPrefix={branchPrefixInputValue} />}
      </SearchableSetting>
    ) : null,
    matchesSettingsSearch(searchQuery, {
      title: getJiraIssueKeyCasingTitle(),
      description: getJiraIssueKeyCasingDescription(),
