      projectHostSetupId: 'remote-repo',
      linkedGitLabMR: null,
      linkedGitLabIssue: null,
      isArchived: true,
      isUnread: true,
      isPinned: true,
      sortOrder: 5,
      lastActivityAt: 1000,
      workspaceStatus: 'in-review',
      diffComments: [],
      priorWorktreeIds: ['repo1::/workspaces/old-feature'],
      automationProvenance: {
