      linkedGiteaPR: null,
      linkedWorkItem: null,
      linkedTaskSourceContext: null,
      mobileDiffReview: undefined,
      projectId: 'github:stablyai/orca',
      hostId: 'ssh:openclaw-2',
      projectHostSetupId: 'remote-repo',
