    )
    expect(setDisplayName).toHaveBeenCalledWith(WORKTREE_ID, 'Fix auth')
    expect(onRenamed).toHaveBeenCalledWith(REPO_ID)
  })

  it('strips a prefix the model leaked into the slug from both branch and display name', async () => {
