export function computeBranchName(
  sanitizedName: string,
  settings: Parameters<typeof selectBranchPrefixInput>[0],
  gitUsername: string | null
): string {
  const prefix = getConfiguredBranchPrefix(settings, gitUsername)
  return prefix
