    : sanitizedName
}

/** Strip the configured prefix and separator; branches built another way fall back to their last path segment. */
export function getBranchLeaf(
  branch: string,
  settings: Parameters<typeof selectBranchPrefixInput>[0],
  gitUsername: string | null
): string {
  const prefix = getConfiguredBranchPrefix(settings, gitUsername)
  const head = prefix ? `${prefix}${resolveBranchPrefixSeparator(settings)}` : null
  if (head && branch.length > head.length && branch.startsWith(head)) {
    return branch.slice(head.length)
  }
  return branch.slice(branch.lastIndexOf('/') + 1)
}

